package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Barcha zararlardan himoya", "Alloh nomi bilan yerdagi va osmondagi hech narsa zarar keltira olmaydigan Alloh nomi bilan boshlayman. U o'ta eshitguvchi va bilguvchi zotdir.", "Har kuni ertalab va kechqurun uch marta.", "Kim ertalab va kechqurun uch marta aytsa, unga hech narsa zarar keltirmaydi."),
        "dua_raditu_billahi" to DuaText("Allohga Rabbiy sifatida rozi bo'lish", "Men Allohdan Robbim, Islom dinim va Muhammad ﷺ Payg'ambarim deb roziman.", "Ertalab va kechqurun uch marta.", "Qiyomat kuni uni rozi qilish Allohning zimmasidagi haqdir."),
        "dua_hasbiyallah" to DuaText("Hasbiyalloh (Alloh kifoyadir)", "Menga Alloh kifoyadir. Undan o'zga iloh yo'q. Unga tavakkul qildim va U aziz arsh egasidir.", "Ertalab va kechqurun etti marta.", "Qur'on oyati; Dunyo va oxirat tashvishlariga Alloh kifoya qiladi."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Subhanallohi va bihamdihi", "Alloh taologa pok va hamdu sanolar bo'lsin.", "Kuniga yuz marta.", "Kim kuniga yuz marta aytsa, gunohlari dengiz ko‘pikiday bo‘lsa ham kechiriladi."),
        "dua_tahleel_100" to DuaText("La ilaha illallohu vahdahu", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir va U har bir narsaga qodirdir.", "Buni kuniga yuz marta aytish katta fazilatdir.", "O'n bandani ozod qilishning savobi, yuzta yaxshilik yozilishi, yuzta gunohning o'chirilishi va kechgacha shaytondan panoh."),
        "dua_leaving_mosque" to DuaText("Masjiddan chiqish", "Allohim, sendan fazlu fazl so'rayman.", "Masjiddan chap oyoq bilan chiqayotganda.", "Masjiddan chiqayotganda Allohdan fazl va rizq so‘rash."),
        "dua_after_adhan" to DuaText("Azondan keyin", "Ey, bu komil da`vat va ado etilayotgan namozning Robbisi, Allohim, Muhammad alayhissalomga ﷺ al-Vasila va fazilat ato et va uni O`zing va`da qilgan maqtov maqomiga ko`targin.", "Azon tamom bo'lgandan keyin.", "Kim buni aytsa, qiyomat kunida Payg'ambarimiz ﷺ shafoatiga erishiladi."),
        "dua_after_salah_istighfar" to DuaText("Farz namozdan keyin", "Allohdan mag'firat so'rayman (3 marta). Allohim, Sen as-salomsan va salom Sendandir. Sen muboraksan, ey ulug‘lik va ikrom sohibi.", "Salomdan keyin darhol.", "Rasululloh ﷺ har farz namozdan keyin buni o'qidilar."),
        "dua_after_salah_help_dhikr" to DuaText("Seni eslashimga yordam ber", "Allohim, Seni zikr qilishimga, Senga shukr qilishimga va Senga eng go'zal tarzda ibodat qilishimga yordam ber.", "Har bir namozdan keyin - Payg'ambarimiz ﷺ Muoz (RA) ga buni o'qishni maslahat berdilar.", "Payg'ambarning maxsus nasihatlari ﷺ - ibodatda mukammallik va doimiylik."),
        "dua_sleep_tasbeeh" to DuaText("Tasbehi Fotimiy uyqudan oldin", "Alloh taologa pokdir (33), hamdlar Alloh uchundir (33), Alloh buyukdir (34).", "Uxlashdan oldin - Payg'ambar ﷺ Fotima va Aliga o'rgatgan (RA).", "Payg'ambarimiz ﷺ u siz uchun xizmatkordan yaxshiroqdir, dedilar."),
        "dua_sleep_qina_adhab" to DuaText("Jazodan himoya qilish", "Allohim, bandalaringni qayta tiriltirgan kuningda meni azobingdan saqla.", "Uch marta, o'ng qo'l bilan yonoq ostiga qo'yilgan.", "Uyquni o'limni eslatishga va oxiratga tayyorgarlikka aylantiradi."),
        "dua_bad_dream" to DuaText("Yomon tushdan keyin", "Men la’nati shaytondan Allohdan panoh tilayman.", "Yomon tushdan keyin: uch marta chapga ozgina tupuring, so'ngra boshqa tomonga buriling.", "Yomon tush sizga zarar keltirmaydi; bu haqda hech kimga aytmang."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Yo Hayyu Ya Qayyum", "Ey barhayot, ey hamma narsaning Parvardigori! Sening rahmating ila yordam so'rayman.", "Ish juda og'irlashganda.", "Payg'ambarimiz ﷺ biror narsa xafa bo'lsa, shunday der edilar."),
        "dua_entering_market" to DuaText("Bozorga kirish", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir. U tiriltirur va o'ldiradi. U tirikdir va o'lmas. Yaxshilik Uning qo'lidadir va U har narsaga qodirdir.", "Bozorga kirganingizda.", "Hadisda buning uchun katta ajr (million yaxshilik) borligi aytilgan."),
        "dua_adam_forgiveness" to DuaText("Odam Atoning duosi (AS)", "Ey Robbimiz, biz o'zimizga zulm qildik, agar bizni mag'firat qilmasang va rahm qilmasang, albatta ziyon ko'ruvchilardan bo'lamiz.", "Odam va Havvaning tavba duosi (AS).", "Insoniyatning birinchi tavbasi - Alloh uni qabul qildi."),
        "dua_abu_bakr" to DuaText("Abu Bakrga duo o'rgatdi (RA)", "Allohim, men o‘zimga katta zulm qildim, gunohlarni Sendan boshqa hech kim kechirmas, meni O‘z huzuringdan mag‘firat et va menga rahm qil. Albatta, Sen mag'firatli va rahmlisan.", "Payg'ambarimiz ﷺ Abu Bakr as-Siddiq (RA) namozda (tashahhuddan keyin) aytishni o'rgatganlar.", "Namozning oxiri uchun sunnat duo."),
        "dua_astaghfirullah_atubu" to DuaText("Kundalik Istig'for", "Allohdan mag'firat so'rayman va Unga tavba qilaman.", "Payg'ambar ﷺ kuniga yetmish martadan ortiq istig'for so'rar edi.", "Nabiy sollallohu alayhi vasallam ﷺ dedilar: Men har kuni yetmish martadan ortiq Allohdan istig'for aytaman va Unga tavba qilaman."),
        "dua_laylatul_qadr" to DuaText("Qadr kechasi uchun duo", "Allohim, Sen mag'firatlisan va kechirishni yaxshi ko'rasan, meni kechir.", "Oisha onamizga (RA) Qadr kechasi uchun o‘rgatilgan.", "Ramazonning oxirgi kechalari va Qadr kechalari uchun maxsus duo."),
        "dua_family_coolness" to DuaText("Ko'zlarning sovuqligi (turmush o'rtog'i va bolalari)", "Parvardigorimiz, bizlarga juftlarimiz va zurriyotlarimizdan ko‘zlarimiz salqinligini ato et va bizlarni solihlarning yetakchilaridan qil.", "Solih turmush o'rtog'i va farzandlari uchun Qur'on duosi.", "Uyda tinchlik va solih bolalar uchun."),
        "dua_righteous_children" to DuaText("Solih nasl uchun", "Parvardigorim, menga Oʻz huzuringdan pokiza zurriyot ato et. Albatta, Sen duoni eshitguvchisan.", "Zakariyo payg'ambar duolari (AS).", "Farzand izlayotganlar uchun Qur'on duosi."),
        "dua_ibrahim_prayer_family" to DuaText("Ibodat asoschilari", "Ey Robbim, meni va zurriyotimdan namozni to'kis ado etuvchi qilgin. Robbimiz, duolarimni qabul qil. Robbimiz, meni, ota-onamni va mo'minlarni hisob-kitob kunida mag'firat qilgin.", "Ibrohim payg'ambarning o'zi va uning avlodlari uchun duosi (AS).", "Odatda namoz oxirida o'qiladi."),
        "dua_newlywed" to DuaText("Yangi turmush qurganlarni tabriklash", "Alloh taolo sizga baraka bersin, sizga salovot yuborsin va ikkalangizni yaxshilikda birlashtirsin.", "Birovni nikohi bilan tabriklaganda.", "Nikoh uchun sunnat tabriklari."),
        "dua_before_eating" to DuaText("Ovqatlanishdan oldin", "Alloh nomi bilan. (Unutilgan bo'lsa:) Boshida va oxirida Allohning nomi bilan.", "Ovqatlanishdan oldin. Agar unutib qo'ysangiz, uni yarmida ayting.", "\"Bismillah\" deyish shaytonni taomni baham ko'rishdan saqlaydi."),
        "dua_after_eating" to DuaText("Ovqatdan keyin", "Menga hech qanday kuch va kuch-qudratsiz uni rizqlantirgan va menga rizq bergan Allohga hamdlar bo'lsin.", "Ovqatni tugatgandan keyin.", "Aytganning o'tgan gunohlari kechiriladi."),
        "dua_host" to DuaText("Xost uchun", "Allohim, ularga rizq qilib bergan narsangda baraka ber, ularni mag‘firat qil va ularga rahm qil.", "Uy egasi uchun, birovning uyida ovqatlangandan keyin.", "Sunnat yo'lida mezbonga rahmat aytish."),
        "dua_breaking_fast" to DuaText("Ro'za Idorasi", "Chanqoqlik ketdi, tomirlar namlandi, Alloh xohlasa, savob tasdiqlandi.", "Iftorlik vaqtida.", "Rasululloh ﷺ iftor paytida shunday dedilar."),
        "dua_new_clothes" to DuaText("Yangi kiyim kiyish", "Allohim, senga hamdlar bo'lsin. Sen meni bu bilan kiyintirding. Men Sendan uning yaxshiligini va u uchun yaratilgan narsaning yaxshiligini so'rayman va uning yomonligidan va u uchun yaratilgan narsaning yomonligidan Sendan panoh tilayman.", "Yangi kiyim kiyganda (uni nomlash, masalan, ko'ylak yoki salla).", "Rasululloh ﷺ bu duoni yangi kiyim kiyganlarida qilganlar. (Kiyinish uchun kunlik duo \"Kiyinish\" ostidadir.)"),
        "dua_rabbana_atina" to DuaText("Bu dunyo va oxiratda yaxshilik", "Ey Robbimiz, bizga bu dunyoda ham, oxiratda ham yaxshilik ato et va bizni do'zax azobidan saqla.", "Payg'ambar alayhissalomning ﷺ duosi eng ko'p aytilgan.", "Dunyo va oxiratning barcha yaxshiliklarini jamlaydigan duo."),
        "dua_rabbi_zidni_ilma" to DuaText("Bilimni oshirish", "Robbim, ilmimni ziyoda qilgin.", "Bilimni oshirish uchun.", "Alloh taolo Payg'ambarga ﷺ ilmni oshirishni so'rashni buyurgan."),
        "dua_musa_sharh_sadr" to DuaText("Ko'krakning ochilishi (Muso alayhissalom)", "Parvardigorim, mening ko‘ksimni keng qil, ishimni yengil qil va tilimdagi tugunni yechib ber, toki ular gapimni tushunishlari uchun.", "Imtihon, nutq yoki har qanday qiyin vazifa oldidan.", "Muso payg'ambarning duosi (AS) - qalb xotirjamligi va ishda yengillik."),
        "dua_la_tuzigh" to DuaText("Yurakning mustahkamligi", "Ey Robbimiz, bizlarni hidoyat qilganingdan keyin qalblarimizni og'dirmagin va bizga O'z huzuringdan rahmat ato et. Albatta, Sen ato etuvchisan.", "Hidoyatga sodiqlik uchun.", "Imonda mustahkam qolish uchun duo."),
        "dua_ya_muqallib" to DuaText("Ey yuraklarni aylantiruvchi", "Ey qalblarni aylantiruvchi, qalbimni diningda mustahkam tutgin.", "Payg'ambar ﷺ tez-tez bu duoni qilgan.", "Ummu Salama (RA) ga ko'ra, Rasululloh ﷺ ko'pincha qilgan duolar."),
        "dua_la_tuakhidhna" to DuaText("Baqara surasining oxirgi oyatlari", "Robbimiz, agar unutsak yoki xato qilsak, bizni jazoga tortmagin. Ey Robbimiz, bizdan oldingilarga yuklaganingdek, bizga ham yuk berma. Ey Robbimiz, bizni ko'tara olmaydigan narsalarni yuklamagin. Bizni kechir, bizni kechir va bizga rahm qil. Sen bizning valiymizsan, bas, kofir qavmga qarshi bizga yordam ber.", "Kechasi uxlashdan oldin - Baqara surasining oxirgi ikki oyati.", "Kim kechasi “Baqara” surasining oxirgi ikki oyatini o‘qisa, o‘zi kifoya qiladi."),
        "dua_visiting_sick" to DuaText("Bemorlarni ziyorat qilish", "Ulugʻ arsh egasi boʻlmish Alloh taolodan shifo soʻrayman.", "Bemorlarni ziyorat qilganda etti marta.", "Agar o'lim vaqti kelmagan bo'lsa, Alloh unga shifo beradi."),
        "dua_ruqyah_pain" to DuaText("Tana og'rig'i uchun", "Men his qilayotgan va qo'rqqan narsalarimning yomonligidan Allohga va Uning qudratiga panoh so'rayman.", "Qo'lingizni og'riyotgan joyga qo'ying, uch marta \"Bismillah\" ayting, keyin bu duoni etti marta ayting.", "Payg'ambar ﷺ Usmon ibn Abil-'Os (RA) og'riq uchun uni o'rgatgan."),
        "dua_ruqyah_nabawi" to DuaText("Bemorlar uchun Payg'ambarlik Ruqyasi", "Ey insonlar Parvardigori Alloh! Zararni yo'qot va shifo ber, chunki Sen shifo beruvchisan. Sening shifongdan o'zga davo yo'q – hech bir kasallik qoldirmaydigan shifo.", "Bemorning ustiga qo'l uzatayotganda.", "Payg'ambar ﷺ oila a'zolarining kasal a'zolarini ziyorat qilganlarida buni o'qigan."),
        "dua_kalimat_tammat" to DuaText("Mukammal so'zlar bilan panoh izlash", "Alloh taoloning mukammal kalomi bilan yaratgan narsalarining yomonligidan panoh tilayman.", "Bir joyda to'xtaganda yoki kechqurun.", "Kim bir joyda to'xtab, shu gapni aytsa, uni tark etmaguncha unga hech narsa zarar yetkazmaydi."),
        "dua_evil_eye" to DuaText("Bolalar uchun himoya (yomon ko'z)", "Sizlar uchun Allohning mukammal kalomi bilan har bir shaytondan, har qanday zaharli maxluqdan va har qanday zararli ko'zdan panoh tilayman.", "Payg'ambar ﷺ Hasan va Husaynga (RA) o'qigan.", "Bolalarni yomon ko'zdan va yomonlikdan saqlash uchun sunnat duo (bir bola uchun \"U'idhuka\" deyish)."),
        "dua_seeing_afflicted" to DuaText("Kimnidir sinovda ko'rish", "Sizlarni sinagan narsasidan meni saqlagan va ko'p maxluqotlaridan meni afzal qilgan Allohga hamdlar bo'lsin.", "Kimnidir sudda ko'rganingizda (o'zingizga jimgina ayting).", "Buni aytgan kishi o'sha sinovdan himoyalangan."),
        "dua_istikhara" to DuaText("Namoz ul-Istixara", "Allohim, ilming ila yaxshilikni, qudrating ila qobiliyatni izlayman va Sendan buyuk fazlingni so'rayman. Sizda kuch bor, menda esa yo'q; Sen bilasan, men bilmayman. Sen g‘aybni bilguvchisan. Allohim, agar bu ish (uni yodga keltirish) sening ilmingda dinim, hayotim va oqibatim uchun foydali boʻlsa, uni menga hukm qil, uni menga oson qil va menga barakali qilgin. Va agar bu ish sening bilimingda dinim, hayotim va oqibatim uchun yomon bo‘lsa, uni mendan qaytar va meni undan qaytar va qayerda bo‘lmasin, menga yaxshilikni amr et, meni unga qanoat qil.", "Ikki rakat nafl namozdan so'ng, joiz bo'lgan ishda eng yaxshisini izlash.", "Payg'ambarimiz ﷺ sahobalarga Qur'on surasini o'rgatganlaridek, barcha ishlarda istixorani o'rgatganlar."),
    )
}
